let sh;
let img;

// before being written as a palette
let workingColors = [];

function preload(){
	// img = loadImage('https://openprocessing.org/sketch/981092/files/lucas-pezeta.jpg');
	// img = loadImage('https://openprocessing.org/sketch/981092/files/cottonbro.png');
	img = loadImage('https://openprocessing.org/sketch/981092/files/sharon-mccutcheon.jpg');
}

function setup() {
	createCanvas(img.width, img.height, WEBGL);

	sh = createShader(vert, frag);
	shader(sh);
}

function draw() {
	background(0);
	translate(-img.width/2, -img.height/2);

	sh.setUniform('img', img);
	sh.setUniform('res', [img.width, img.height]);
	sh.setUniform('time', millis());

	rect(0, 0, img.width, img.height, 1, 1);
}







// === Tab: vert ===


let vert = `
#ifdef GL_ES
	precision highp float;
	precision mediump int;
#endif

attribute vec3 aPosition;
attribute vec4 aVertexColor;
attribute vec3 aNormal;
attribute vec2 aTexCoord;

varying vec3 var_vertPos;
varying vec4 var_vertCol;
varying vec3 var_vertNormal;
varying vec2 var_vertTexCoord;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

void main() {
	gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0 );
	var_vertPos = aPosition;
	var_vertCol = aVertexColor;
	var_vertNormal = aNormal;
	var_vertTexCoord = aTexCoord;
}
`;



// === Tab: frag ===

let frag = `
#ifdef GL_ES
precision mediump float;
#endif

varying vec2 var_vertTexCoord;

uniform sampler2D img;

uniform vec2 res;
uniform float time;

float diff(vec3 col1, vec3 col2){
  float d = 0.0;
  d += pow( col1.r - col2.r, 2.0);
  d += pow( col1.g - col2.g, 2.0);
  d += pow( col1.b - col2.b, 2.0);
  return sqrt(d);
}

vec3 rgb2hsv(vec3 c)
{
    vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));

    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

vec3 hsv2rgb(vec3 c)
{
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void main(){
	vec2 uv = vec2(var_vertTexCoord);
	vec3 col = vec3(texture2D(img, uv));

	vec3 hsv = rgb2hsv(col);

	float h = hsv.x + mod(time/3000.0, 1.0);

  vec3 final = hsv2rgb( vec3(h, hsv.yz));

	gl_FragColor = vec4(final, 1.0);
}
`;

